try:
    print('>>> f = getattr')
    print('>>> x = slice(0)')
    print('>>> y = {}')
    print('>>> f(x, y)')
    f = getattr
    x = slice(0)
    y = {}
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
